python3 -c "
import json
data = json.load(open('/app/resources/treasury_bulletin_2000_09.json'))
def search(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'debt' in k.lower() or 'sustain' in k.lower() or 'indicator' in k.lower() or 'dsi' in k.lower():
                print(f'{path}.{k}')
            search(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj[:5]):
            search(item, f'{path}[{i}]')
search(data)
